function lpc_reply(array $x,int $s=200):void{http_response_code($s);echo json_encode($x,JSON_UNESCAPED_SLASHES);exit;}
function lpc_body():array{$raw=file_get_contents('php://input');$x=json_decode((string)$raw,true);return is_array($x)?$x:$_POST;}
function lpc_norm(string $s):string{$s=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/',' ',$s)));return trim(preg_replace('/\s+/',' ',$s));}
function lpc_user():array{$u=current_user();return['id'=>(int)($u['id']??0),'name'=>(string)($u['name']??$u['full_name']??'Owner')];}
function lpc_prefix(string $name):string{$ignore=['and','of','the','with'];$words=array_values(array_filter(explode(' ',lpc_norm($name)),function($w)use($ignore){return $w!==''&&!in_array($w,$ignore,true);}));if(count($words)>1){$p='';foreach(array_slice($words,0,3)as$w)$p.=substr($w,0,1);}else{$p=substr((string)($words[0]??'prd'),0,3);}return strtoupper(strlen($p)<2?str_pad($p,2,'X'):$p);}
function lpc_code(PDO $pdo,string $name):string{$p=lpc_prefix($name);$st=$pdo->prepare('SELECT short_code FROM cw_cost_products WHERE short_code LIKE ? ORDER BY id DESC');$st->execute([$p.'%']);$used=array_flip($st->fetchAll(PDO::FETCH_COLUMN));for($n=1;$n<100000;$n++){$c=$p.str_pad((string)$n,3,'0',STR_PAD_LEFT);if(!isset($used[$c]))return$c;}throw new RuntimeException('A unique short code could not be generated.');}
function lpc_basis(array $line):array{$u=(string)($line['base_unit']??$line['purchase_unit']??'');if(in_array($u,['kg','g'],true))return['weight','kg'];if(in_array($u,['L','ml'],true))return['volume','L'];if($u==='unit')return['count','each'];if($u==='pack')return['ready_made','unit'];return[null,null];}
function lpc_quantity(array $line,$basis):float{$q=(float)($line['base_quantity']??0);$u=(string)($line['base_unit']??'');if($q<=0){$q=(float)($line['quantity']??0);$pack=(float)($line['pack_size']??0);if($pack>0)$q*=$pack;$u=(string)($line['purchase_unit']??'');}if($basis==='weight'&&$u==='g')$q/=1000;if($basis==='volume'&&$u==='ml')$q/=1000;return$q;}
function lpc_source_cost(array $line):?float{$currency=strtoupper((string)$line['currency']);$confirmed=(float)($line['purchase_cost_in_landed']??0);if($currency!=='NAD')return$confirmed>0?$confirmed:null;if($confirmed>0)return$confirmed;$vat=(string)$line['vat_treatment'];if(in_array($vat,['inclusive','mixed'],true)&&(float)$line['line_subtotal']>0)return(float)$line['line_subtotal'];if($vat==='exclusive'&&(float)$line['line_subtotal']>0)return(float)$line['line_subtotal'];if($vat==='exempt')return(float)($line['line_total']??0);return null;}
function lpc_snapshot(PDO $pdo,int $productId,int $sourceId,?int $supplierId,?int $lineId,?int $transportProductId,string $basis,string $unit,float $qty,float $supplier,float $transport,string $currency,string $date,string $status):bool{$spb=$qty>0?$supplier/$qty:0;$tpb=$qty>0?$transport/$qty:0;$hash=hash('sha256',implode('|',[$productId,$sourceId,$lineId?:0,$transportProductId?:0,$basis,$unit,sprintf('%.8F',$qty),sprintf('%.8F',$supplier),sprintf('%.8F',$transport),$currency,$date,$status]));$st=$pdo->prepare('SELECT COUNT(*) FROM cw_landed_product_costs WHERE calculation_hash=?');$st->execute([$hash]);if((int)$st->fetchColumn())return false;$v=$pdo->prepare('SELECT COALESCE(MAX(calculation_version),0)+1 FROM cw_landed_product_costs WHERE product_source_id=?');$v->execute([$sourceId]);$version=(int)$v->fetchColumn();$u=lpc_user();$pdo->prepare('INSERT INTO cw_landed_product_costs(product_id,product_source_id,supplier_id,supplier_invoice_line_id,transport_product_allocation_id,costing_basis,base_unit,base_quantity,supplier_cost_used,transport_cost_used,supplier_cost_per_base,transport_cost_per_base,landed_cost_per_base,currency,cost_date,status_key,calculation_version,calculation_hash,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$productId,$sourceId,$supplierId,$lineId,$transportProductId,$basis,$unit,$qty,$supplier,$transport,$spb,$tpb,$spb+$tpb,$currency,$date,$status,$version,$hash,$u['id'],$u['name']]);return true;}
function lpc_refresh(PDO $pdo):array{$sql="SELECT l.*,i.supplier_id,i.supplier_name,i.invoice_number,i.invoice_date,i.currency,i.exchange_rate,i.vat_treatment,i.approval_status FROM cw_supplier_invoice_lines l JOIN cw_supplier_invoices i ON i.id=l.supplier_invoice_id WHERE i.approval_status='approved' AND l.review_status='valid' AND l.item_type NOT IN('packaging','additional_cost','unclassified') ORDER BY i.invoice_date,l.id";$lines=$pdo->query($sql)->fetchAll();$created=0;$snapshots=0;$pdo->beginTransaction();foreach($lines as$line){$name=trim((string)$line['product_description']);if($name==='')continue;[$basis,$unit]=lpc_basis($line);$qty=lpc_quantity($line,$basis);$cost=lpc_source_cost($line);$norm=lpc_norm($name);$pid=0;$find=$pdo->prepare('SELECT id,costing_basis,base_unit FROM cw_cost_products WHERE (woo_product_id IS NOT NULL AND woo_product_id=? AND COALESCE(woo_variation_id,0)=?) OR normalized_name=? ORDER BY woo_product_id IS NOT NULL DESC,id LIMIT 1');$find->execute([(int)($line['woo_product_id']??0),(int)($line['woo_variation_id']??0),$norm]);$p=$find->fetch();if($p)$pid=(int)$p['id'];else{$cat=(string)($line['product_category']??'');$sku=(string)($line['supplier_sku']??'');if((int)($line['woo_product_id']??0)>0){$s=$pdo->prepare("SELECT sku,category FROM cw_product_snapshots WHERE product_id=? AND variation_id=? AND sync_batch_id=(SELECT id FROM cw_sync_batches WHERE is_successful_snapshot=1 ORDER BY completed_at DESC,id DESC LIMIT 1) LIMIT 1");$s->execute([(int)$line['woo_product_id'],(int)($line['woo_variation_id']??0)]);$w=$s->fetch();if($w){$sku=(string)$w['sku'];if((string)$w['category']!=='')$cat=(string)$w['category'];}}$u=lpc_user();$pdo->prepare('INSERT INTO cw_cost_products(product_name,normalized_name,short_code,woo_product_id,woo_variation_id,woo_sku,product_category,costing_basis,base_unit,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$name,$norm,lpc_code($pdo,$name),(int)($line['woo_product_id']??0)?:null,(int)($line['woo_variation_id']??0)?:null,$sku,$cat,$basis,$unit,$u['id'],$u['name']]);$pid=(int)$pdo->lastInsertId();$created++;}$src=$pdo->prepare('SELECT id FROM cw_cost_product_sources WHERE supplier_invoice_line_id=?');$src->execute([(int)$line['id']]);$sourceId=(int)($src->fetchColumn()?:0);if(!$sourceId){$pdo->prepare("INSERT INTO cw_cost_product_sources(product_id,supplier_id,supplier_name,supplier_invoice_line_id,source_type,cost_date,total_purchased_quantity,total_supplier_cost,currency,vat_treatment,created_by,created_by_name) VALUES(?,?,?,?,'invoice',?,?,?,?,?,?,?)")->execute([$pid,$line['supplier_id']?:null,$line['supplier_name'],(int)$line['id'],$line['invoice_date']?:date('Y-m-d'),$qty,$cost?:0,$line['currency'],$line['vat_treatment'],lpc_user()['id'],lpc_user()['name']]);$sourceId=(int)$pdo->lastInsertId();}else{$pdo->prepare('UPDATE cw_cost_product_sources SET product_id=?,supplier_id=?,supplier_name=?,cost_date=?,total_purchased_quantity=?,total_supplier_cost=?,currency=?,vat_treatment=? WHERE id=?')->execute([$pid,$line['supplier_id']?:null,$line['supplier_name'],$line['invoice_date'],$qty,$cost?:0,$line['currency'],$line['vat_treatment'],$sourceId]);}$ta=$pdo->prepare('SELECT pa.id,COALESCE(pa.override_amount,pa.calculated_amount,0) amount FROM cw_transport_product_allocations pa JOIN cw_transport_allocations a ON a.id=pa.transport_allocation_id JOIN cw_transport_records t ON t.id=a.transport_id WHERE pa.supplier_invoice_line_id=? AND t.allocation_status<>'archived' ORDER BY t.transport_date DESC,pa.id DESC LIMIT 1');$ta->execute([(int)$line['id']]);$transport=$ta->fetch();$transportAmount=$transport?(float)$transport['amount']:0;$status='complete';if(!$basis)$status='missing_costing_basis';elseif($qty<=0)$status='missing_quantity';elseif($cost===null||$cost<=0)$status=strtoupper((string)$line['currency'])!=='NAD'?'exchange_rate_required':'missing_supplier_cost';elseif(!$transport)$status='transport_not_allocated';if($basis&&$unit&&$qty>0&&$cost!==null&&$cost>0)$snapshots+=lpc_snapshot($pdo,$pid,$sourceId,$line['supplier_id']?:(null),(int)$line['id'],$transport?(int)$transport['id']:null,$basis,$unit,$qty,$cost,$transportAmount,(string)$line['currency'],(string)$line['invoice_date'],$status)?1:0;}$pdo->commit();return['products_created'=>$created,'snapshots_created'=>$snapshots,'lines_reviewed'=>count($lines)];}
try{$pdo=db();cw_install_schema($pdo);$action=(string)($_GET['action']??'bootstrap');if($_SERVER['REQUEST_METHOD']!=='GET')cw_require_csrf();
if($action==='refresh'){lpc_reply(['ok'=>true,'refresh'=>lpc_refresh($pdo)]);}
if($action==='save-manual'){$b=lpc_body();$id=(int)($b['id']??0);$name=trim((string)($b['product_name']??''));$basis=(string)($b['costing_basis']??'');$unit=(string)($b['base_unit']??'');$qty=(float)($b['total_purchased_quantity']??0);$cost=(float)($b['total_supplier_cost']??0);$transport=(float)($b['transport_allocation']??0);$date=(string)($b['cost_date']??'');$supplier=(int)($b['supplier_id']??0);$validUnits=['weight'=>'kg','volume'=>'L','count'=>'each','ready_made'=>'unit'];if($name===''||!isset($validUnits[$basis])||$validUnits[$basis]!==$unit||$qty<=0||$cost<0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$supplier<1)throw new RuntimeException('Complete the product, supplier, basis, matching base unit, date, quantity and cost.');$u=lpc_user();$pdo->beginTransaction();if($id){$st=$pdo->prepare('SELECT short_code FROM cw_cost_products WHERE id=? FOR UPDATE');$st->execute([$id]);$old=$st->fetch();if(!$old)throw new RuntimeException('Product not found.');$code=trim((string)($b['short_code']??$old['short_code']));$pdo->prepare('UPDATE cw_cost_products SET product_name=?,normalized_name=?,short_code=?,woo_product_id=?,product_category=?,costing_basis=?,base_unit=?,notes=?,updated_by=?,updated_by_name=? WHERE id=?')->execute([$name,lpc_norm($name),$code,(int)($b['woo_product_id']??0)?:null,trim((string)($b['product_category']??'')),$basis,$unit,trim((string)($b['notes']??'')),$u['id'],$u['name'],$id]);$pid=$id;}else{$code=trim((string)($b['short_code']??''));if($code==='')$code=lpc_code($pdo,$name);$pdo->prepare('INSERT INTO cw_cost_products(product_name,normalized_name,short_code,woo_product_id,product_category,costing_basis,base_unit,notes,created_by,created_by_name) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$name,lpc_norm($name),$code,(int)($b['woo_product_id']??0)?:null,trim((string)($b['product_category']??'')),$basis,$unit,trim((string)($b['notes']??'')),$u['id'],$u['name']]);$pid=(int)$pdo->lastInsertId();}$sn=$pdo->prepare('SELECT name FROM cw_suppliers WHERE id=?');$sn->execute([$supplier]);$supplierName=(string)$sn->fetchColumn();if($supplierName==='')throw new RuntimeException('Select a valid supplier.');$pdo->prepare("INSERT INTO cw_cost_product_sources(product_id,supplier_id,supplier_name,manual_reference,source_type,cost_date,total_purchased_quantity,total_supplier_cost,currency,vat_treatment,notes,created_by,created_by_name) VALUES(?,?,?,?,'manual',?,?,?,?,?,?,?,?)")->execute([$pid,$supplier,$supplierName,trim((string)($b['manual_reference']??'')),$date,$qty,$cost,'NAD',(string)($b['vat_treatment']??'recoverable'),trim((string)($b['notes']??'')),$u['id'],$u['name']]);$src=(int)$pdo->lastInsertId();lpc_snapshot($pdo,$pid,$src,$supplier,null,null,$basis,$unit,$qty,$cost,$transport,'NAD',$date,$transport>0?'complete':'transport_not_allocated');$pdo->commit();lpc_reply(['ok'=>true,'id'=>$pid,'short_code'=>$code]);}
if($action==='history'){$id=(int)($_GET['product_id']??0);$st=$pdo->prepare('SELECT c.*,s.supplier_name,s.manual_reference,i.invoice_number FROM cw_landed_product_costs c JOIN cw_cost_product_sources s ON s.id=c.product_source_id LEFT JOIN cw_supplier_invoices i ON i.id=(SELECT supplier_invoice_id FROM cw_supplier_invoice_lines WHERE id=c.supplier_invoice_line_id) WHERE c.product_id=? ORDER BY c.cost_date DESC,c.id DESC');$st->execute([$id]);lpc_reply(['ok'=>true,'rows'=>$st->fetchAll()]);}
if($action==='bootstrap'){$rows=$pdo->query("SELECT c.*,p.product_name,p.short_code,p.woo_product_id,p.woo_sku,p.product_category,p.active,s.supplier_name,s.source_type,s.manual_reference,i.id supplier_invoice_id,i.invoice_number,i.invoice_date,t.transport_id,COALESCE(pk.setup_count,0) packaging_count,pk.setup_preview FROM cw_landed_product_costs c JOIN cw_cost_products p ON p.id=c.product_id JOIN cw_cost_product_sources s ON s.id=c.product_source_id LEFT JOIN cw_supplier_invoices i ON i.id=(SELECT supplier_invoice_id FROM cw_supplier_invoice_lines WHERE id=c.supplier_invoice_line_id) LEFT JOIN cw_transport_product_allocations pa ON pa.id=c.transport_product_allocation_id LEFT JOIN cw_transport_allocations t ON t.id=pa.transport_allocation_id LEFT JOIN (SELECT p2.id product_id,COUNT(DISTINCT ps.id) setup_count,GROUP_CONCAT(DISTINCT CONCAT(z.label,' · N$',FORMAT(x.total_inc,2)) ORDER BY z.base_value SEPARATOR ', ') setup_preview FROM cw_cost_products p2 JOIN cw_packaging_setups ps ON ps.active=1 AND ((ps.scope_type='product' AND (ps.scope_reference=CAST(p2.woo_product_id AS CHAR) OR LOWER(ps.scope_label)=LOWER(p2.product_name))) OR (ps.scope_type='category' AND LOWER(ps.scope_label)=LOWER(p2.product_category)) OR ps.scope_type='default') JOIN cw_size_conversions z ON z.id=ps.size_conversion_id LEFT JOIN (SELECT packaging_setup_id,SUM(component_cost_inc) total_inc FROM cw_packaging_setup_components GROUP BY packaging_setup_id)x ON x.packaging_setup_id=ps.id GROUP BY p2.id)pk ON pk.product_id=p.id WHERE c.id=(SELECT c2.id FROM cw_landed_product_costs c2 WHERE c2.product_source_id=c.product_source_id ORDER BY c2.cost_date DESC,c2.id DESC LIMIT 1) ORDER BY c.cost_date DESC,p.product_name,s.supplier_name")->fetchAll();$suppliers=$pdo->query('SELECT id,name FROM cw_suppliers WHERE active=1 ORDER BY name')->fetchAll();$categories=$pdo->query("SELECT DISTINCT category FROM cw_product_snapshots WHERE category IS NOT NULL AND category<>'' AND sync_batch_id=(SELECT id FROM cw_sync_batches WHERE is_successful_snapshot=1 ORDER BY completed_at DESC,id DESC LIMIT 1) ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);foreach($pdo->query("SELECT DISTINCT product_category FROM cw_supplier_invoice_lines WHERE product_category<>'' ORDER BY product_category")->fetchAll(PDO::FETCH_COLUMN)as$c)if(!in_array($c,$categories,true))$categories[]=$c;natcasesort($categories);$products=$pdo->query("SELECT product_id,variation_id,product_name,variation_name,sku,category FROM cw_product_snapshots WHERE sync_batch_id=(SELECT id FROM cw_sync_batches WHERE is_successful_snapshot=1 ORDER BY completed_at DESC,id DESC LIMIT 1) ORDER BY product_name,variation_name")->fetchAll();lpc_reply(['ok'=>true,'rows'=>$rows,'suppliers'=>$suppliers,'categories'=>array_values($categories),'products'=>$products]);}
throw new RuntimeException('Unsupported action.');}catch(Throwable$e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Landed product costs: '.get_class($e));lpc_reply(['ok'=>false,'message'=>$e->getMessage()],400);}
